cpuProfile.reproductionScript:
import assert from 'node:assert/strict';
import {Session} from 'node:inspector/promises';
import {pathToFileURL} from 'node:url';
const root='/tmp/wt-closed-folding-base';
const {ComputeEngine}=await import(pathToFileURL(root+'/src/compute-engine.ts'));
const {compile}=await import(pathToFileURL(root+'/src/compute-engine/compilation/compile-expression.ts'));
const ce=new ComputeEngine({precision:'machine'});
let e=ce.function('Add',[ce.number(2),ce.function('Sqrt',[ce.number(3)])]);
for(let i=0;i<24;i++)e=ce._fn('Add',[e,e]);
for(let i=0;i<5;i++)assert(compile(e).success);
const results=new Array(100),session=new Session();session.connect();
await session.post('Profiler.enable');await session.post('Profiler.setSamplingInterval',{interval:1000});await session.post('Profiler.start');
for(let i=0;i<results.length;i++)results[i]=compile(e);
const {profile}=await session.post('Profiler.stop');session.disconnect();
for(const r of results){assert(r.success);assert(Math.abs(r.run()-2**24*(2+Math.sqrt(3)))<1e-6);}
const nodes=new Map(profile.nodes.map(n=>[n.id,n])),parents=new Map();
for(const n of profile.nodes)for(const id of n.children??[])parents.set(id,n.id);
const categories={},self=new Map();
for(let i=0;i<profile.samples.length;i++){
 const id=profile.samples[i],weight=profile.timeDeltas[i],node=nodes.get(id);
 const key=node.callFrame.functionName+' '+node.callFrame.url.replace(root,'<root>')+':'+(node.callFrame.lineNumber+1);
 self.set(key,(self.get(key)??0)+weight);
 let current=id,category='other compilation/runtime';
 while(current!==undefined){
  const n=nodes.get(current),name=n.callFrame.functionName;
  if(name==='foldCostEstimate'){category='cost estimation';break;}
  if(name==='evaluateFold'){category='constant evaluation/materialization';break;}
  if(name==='constantFoldValue')category='other folding gates';
  current=parents.get(current);
 }
 categories[category]=(categories[category]??0)+weight;
}
console.log(JSON.stringify({root,depth:24,calls:100,warmup:5,samplingMicroseconds:1000,durationMicroseconds:profile.endTime-profile.startTime,samples:profile.samples.length,categorySampleMicroseconds:categories,topSelfSampleMicroseconds:[...self].sort((a,b)=>b[1]-a[1]).slice(0,25)}));
